 "risks": [
  {
   "id": "no_liability_cap_or_remedies_clause",
   "severity": "low",
   "message": "The NDA has no liability cap or limitation of liability, so exposure for a confidentiality breach is uncapped by contract.",
   "quote": "If the dispute is not resolved within twenty Business Days, either Party may pursue the remedies available to it."
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "low",
   "message": "The agreement does not say whether either party can end it early; it simply runs for a fixed 12 months.",
   "quote": "This Agreement will remain in effect for 12 months from the Effective Date."
  },
  {
   "id": "nonsolicit_binds_northwind",
   "severity": "low",
   "message": "The mutual non-solicitation clause restricts Northwind from soliciting Bluepeak personnel for 12 months after the term, which is unusual in an NDA and extends beyond the 12-month term.",
   "quote": "During the term and for twelve months thereafter, neither Party shall knowingly solicit for employment any Personnel of the other Party who were directly involved in the performance of this Agreement"
  },
  {
   "id": "audit_rights_in_nda",
   "severity": "low",
   "message": "Either party may audit the other's records annually, which is atypical for an NDA and could expose Northwind's records to review by Bluepeak.",
   "quote": "Upon reasonable prior notice and no more than once per year, a Party may audit the other Party's records solely to verify compliance with this Agreement."
  },
  {
   "id": "expired_term",
   "severity": "medium",
   "message": "The 12-month term from February 25, 2026 ended around February 25, 2027 and, as of today (2026-10-14), is still running; confidentiality obligations will then continue 3 years after termination. Confirm whether the relationship will continue beyond the term, since there is no renewal mechanism.",
   "quote": "This Agreement will remain in effect for 12 months from the Effective Date."
  }
 ],
